const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// send() ส่ง request ด้วย fetch แล้วคืนค่า Response
async function withRetry(send, max = 5) {
  for (let i = 0; ; i++) {
    const res = await send();
    if (res.status !== 429 || i >= max) return res;
    // Retry-After ใน header มีหน่วยเป็นวินาที
    const ra = Number(res.headers.get('retry-after')) * 1000;
    const wait = ra || 2 ** i * 500;
    await sleep(wait + Math.random() * 250);
  }
}

