// callModel(messages) -> { stop_reason, content: [ ...blocks ] }
// block แบบ tool_use: { type: 'tool_use', id, name, input }
// tools = { ชื่อ: { validate(input), needsApproval?, run(input) } }
async function runAgent({ callModel, tools, approve, userText }) {
  const messages = [{ role: 'user', content: userText }];
  while (true) {
    const res = await callModel(messages);
    messages.push({ role: 'assistant', content: res.content });
    if (res.stop_reason !== 'tool_use') {
      return res.content.filter((b) => b.type === 'text').map((b) => b.text).join('');
    }
    const results = [];
    for (const block of res.content.filter((b) => b.type === 'tool_use')) {
      const output = await tools[block.name].run(block.input);
      results.push({ type: 'tool_result', tool_use_id: block.id, content: JSON.stringify(output) });
    }
    messages.push({ role: 'user', content: results });
  }
}

