async function runAgent({ callModel, tools, approve, userText, maxSteps = 8 }) {
  const messages = [{ role: 'user', content: userText }];

  async function runTool(block) {
    const result = (content, isError = false) => ({
      type: 'tool_result',
      tool_use_id: block.id,
      content,
      ...(isError ? { is_error: true } : {}),
    });
    try {
      if (!Object.hasOwn(tools, block.name)) {
        return result('ไม่มี tool ชื่อ ' + block.name, true);
      }
      const tool = tools[block.name];
      if (!tool.validate(block.input)) {
        return result('arguments ไม่ถูกต้อง', true);
      }
      if (tool.needsApproval && !(await approve(block.name, block.input))) {
        return result('ผู้ใช้ไม่อนุมัติ', true);
      }
      return result(JSON.stringify(await tool.run(block.input)));
    } catch (err) {
      return result('tool ล้มเหลว: ' + err.message, true);
    }
  }

  for (let step = 0; step < maxSteps; step++) {
    const res = await callModel(messages);
    messages.push({ role: 'assistant', content: res.content });
    if (res.stop_reason !== 'tool_use') {
      return res.content.filter((b) => b.type === 'text').map((b) => b.text).join('');
    }
    const results = [];
    for (const block of res.content.filter((b) => b.type === 'tool_use')) {
      results.push(await runTool(block));
    }
    messages.push({ role: 'user', content: results });
  }
  throw new Error('agent เกินจำนวนรอบที่กำหนด');
}
